 const add=()=>{const result=$('#handwrite-result').value.trim();if(!result)return;const text=$('#handwrite-text');if(text.value.length+result.length+1>100000){c.toast('This note is full. Save it and start another note.');return false;}text.value+=(text.value&&!/\s$/.test(text.value)?' ':'')+result;draft.strokes=[];redo=[];clearResult();paint();persist();controls();return true;};$('#handwrite-add').onclick=add;
 for(const id of ['handwrite-title','handwrite-text','handwrite-result'])$('#'+id).oninput=persist;$('#handwrite-language').onchange=()=>{clearResult();persist();};
